// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertDoesNotThrow;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.nio.file.Path;
import java.util.List;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;

import org.eclipse.rdf4j.model.impl.SimpleValueFactory;
import org.eclipse.rdf4j.sail.backup.BackupRequest;
import org.eclipse.rdf4j.sail.backup.BackupType;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.Timeout;
import org.junit.jupiter.api.io.TempDir;

@Timeout(60)
class LmdbBackupForeignGenerationRetentionTest {

	@Test
	void retentionCannotPruneAnotherSourcesUnacknowledgedReplay(@TempDir Path directory) throws Exception {
		LmdbStore owner = new LmdbStore(directory.resolve("owner").toFile(),
				new LmdbStoreConfig().setBackupJournalEnabled(true));
		LmdbStore foreign = new LmdbStore(directory.resolve("foreign").toFile(),
				new LmdbStoreConfig().setBackupJournalEnabled(true));
		CountDownLatch archived = new CountDownLatch(1);
		CountDownLatch releaseAcknowledgement = new CountDownLatch(1);
		try {
			owner.init();
			foreign.init();
			Path backups = directory.resolve("backups");
			LmdbBackupServiceImpl ownerService = (LmdbBackupServiceImpl) owner.getBackupService();
			LmdbBackupServiceImpl foreignService = (LmdbBackupServiceImpl) foreign.getBackupService();
			// Establish both roots before either publisher has written a transaction. Root selection must not
			// accidentally exercise export filename collisions instead of the retention defect under test.
			ownerService.createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			foreignService.createBackup(BackupRequest.builder(backups, BackupType.FULL).build());
			var ownerGeneration = owner.getBackingStore().backupJournalState().generation();
			var foreignGeneration = foreign.getBackingStore().backupJournalState().generation();
			assertNotEquals(ownerGeneration, foreignGeneration);
			PostCommitBackupPublisher foreignPublisher = foreign.getBackingStore().backupPublisher();
			var originalAcknowledgement = foreignPublisher.checkpointAcknowledgement();
			foreignPublisher.setBeforeAcknowledgement(() -> {
				archived.countDown();
				try {
					if (!releaseAcknowledgement.await(30, TimeUnit.SECONDS)) {
						throw new AssertionError("Foreign acknowledgement was not released");
					}
				} catch (InterruptedException interrupted) {
					Thread.currentThread().interrupt();
					throw new AssertionError(interrupted);
				}
			});
			add(foreign, "foreign");
			long foreignTransaction = foreign.getBackingStore().getCurrentCommittedTxnId();
			assertTrue(archived.await(10, TimeUnit.SECONDS), "Foreign archive must be durable before retention");
			assertTrue(originalAcknowledgement.transaction() < foreignTransaction);
			assertEquals(originalAcknowledgement, foreignPublisher.checkpointAcknowledgement());
			// Borrow the live journal instead of opening a second LMDB environment for the same path. Its
			// publisher is parked outside archive IO until finally releases it, so these direct probes are serialized.
			LmdbBackupJournal foreignJournal = (LmdbBackupJournal) foreignService
					.nativeJournalIdentityForTest(backups, foreignGeneration);
			byte[] replayBytes;
			try (var input = foreignJournal.openStage(foreignTransaction)) {
				replayBytes = input.readAllBytes();
			}
			PostCommitBackupPublisher.Stage stage;
			try (var input = new DataInputStream(new ByteArrayInputStream(replayBytes))) {
				stage = PostCommitBackupPublisher.readStage(input, null);
			}
			// The owner's newer full backup creates a retention cutoff covering the foreign transaction.
			do {
				add(owner, "owner-" + owner.getBackingStore().getCurrentCommittedTxnId());
			} while (owner.getBackingStore().getCurrentCommittedTxnId() <= foreignTransaction);
			long ownerTransaction = owner.getBackingStore().getCurrentCommittedTxnId();
			awaitAcknowledged(owner.getBackingStore().backupPublisher(), ownerTransaction);
			var retained = ownerService.createBackup(BackupRequest.builder(backups, BackupType.FULL)
					.retentionCount(1)
					.build());
			assertTrue(retained.getEndTransactionId() >= foreignTransaction);
			assertEquals(originalAcknowledgement, foreignPublisher.checkpointAcknowledgement(),
					"Retention must not silently acknowledge the other source");
			// Reopening after a crash must replay this exact retained source stage. Prior code advances the
			// foreign journal's prune boundary using the owner's proof, making this append reject valid replay.
			assertDoesNotThrow(() -> foreignJournal.append(List.of(stage),
					ignored -> new ByteArrayInputStream(replayBytes)),
					"The owner's retention must leave the foreign unacknowledged transaction replayable");
			try (var input = foreignJournal.openStage(foreignTransaction)) {
				assertArrayEquals(replayBytes, input.readAllBytes());
			}
		} finally {
			releaseAcknowledgement.countDown();
			try {
				foreign.shutDown();
			} finally {
				owner.shutDown();
			}
		}
	}

	private static void awaitAcknowledged(PostCommitBackupPublisher publisher, long transaction) throws Exception {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(10);
		while (publisher.acknowledgedTransactionId() < transaction && System.nanoTime() < deadline) {
			Thread.sleep(5);
		}
		assertEquals(transaction, publisher.acknowledgedTransactionId());
	}

	private static void add(LmdbStore store, String label) {
		var vf = SimpleValueFactory.getInstance();
		try (var connection = store.getConnection()) {
			connection.begin();
			connection.addStatement(vf.createIRI("urn:retention:" + label), vf.createIRI("urn:retention:p"),
					vf.createLiteral(label));
			connection.commit();
		}
	}
}
